package travelsync;
import java.sql.*;import java.security.*;import java.util.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
final class DB {
 static final String URL="jdbc:postgresql://localhost:5432/travelsync",DB_USER="postgres",DB_PASSWORD="CHANGE_ME";
 static class Destination{int id,km;String name,hotel,attraction;Destination(int i,String n,String h,String a,int k){id=i;name=n;hotel=h;attraction=a;km=k;}}
 static Connection c()throws SQLException{return DriverManager.getConnection(URL,DB_USER,DB_PASSWORD);}
 static void initialize()throws SQLException{try(Connection c=c();Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS app_users(id SERIAL PRIMARY KEY,username VARCHAR(24) UNIQUE NOT NULL,password_hash VARCHAR(64) NOT NULL,password_salt VARCHAR(32) NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('ADMIN','USER')),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");s.executeUpdate("CREATE TABLE IF NOT EXISTS destinations(id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,hotel VARCHAR(150) NOT NULL,attraction VARCHAR(150) NOT NULL,distance_km INT NOT NULL CHECK(distance_km>=0))");}if(destinations().isEmpty()){String[][] a={{"Vijayawada","River View Residency","Kanaka Durga Temple","0"},{"Visakhapatnam","Beach Breeze Hotel","RK Beach","350"},{"Tirupati","Temple Stay Inn","Sri Venkateswara Temple","410"},{"Hyderabad","City Comfort","Charminar","275"},{"Chennai","Marina Bay Lodge","Marina Beach","430"},{"Amaravati","Capital Grand","Undavalli Caves","40"}};for(String[] d:a)save(0,d[0],d[1],d[2],Integer.parseInt(d[3]));}}
 static String hash(String p,byte[] salt)throws Exception{PBEKeySpec s=new PBEKeySpec(p.toCharArray(),salt,120000,256);try{return Base64.getEncoder().encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(s).getEncoded());}finally{s.clearPassword();}}
 static void register(String u,String p)throws Exception{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);try(Connection c=c();PreparedStatement s=c.prepareStatement("INSERT INTO app_users(username,password_hash,password_salt,role) VALUES(?,?,?,'USER')")){s.setString(1,u);s.setString(2,hash(p,salt));s.setString(3,Base64.getEncoder().encodeToString(salt));s.executeUpdate();}}
 static Main.User login(String u,String p,String role)throws Exception{try(Connection c=c();PreparedStatement s=c.prepareStatement("SELECT id,username,password_hash,password_salt,role FROM app_users WHERE lower(username)=lower(?)")){s.setString(1,u);try(ResultSet r=s.executeQuery()){if(!r.next())return null;byte[] salt=Base64.getDecoder().decode(r.getString(4));if(!MessageDigest.isEqual(hash(p,salt).getBytes(),r.getString(3).getBytes())||!role.equals(r.getString(5)))return null;return new Main.User(r.getInt(1),r.getString(2),r.getString(5));}}}
 static void admin(String u,String p)throws Exception{try(Connection c=c();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM app_users WHERE role='ADMIN'")){r.next();if(r.getInt(1)>0)throw new Exception("An admin already exists.");}byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);try(Connection c=c();PreparedStatement s=c.prepareStatement("INSERT INTO app_users(username,password_hash,password_salt,role) VALUES(?,?,?,'ADMIN')")){s.setString(1,u);s.setString(2,hash(p,salt));s.setString(3,Base64.getEncoder().encodeToString(salt));s.executeUpdate();}}
 static List<Destination> destinations()throws SQLException{List<Destination> a=new ArrayList<>();try(Connection c=c();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,hotel,attraction,distance_km FROM destinations ORDER BY id")){while(r.next())a.add(new Destination(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5)));}return a;}
 static Destination get(int id)throws SQLException{try(Connection c=c();PreparedStatement s=c.prepareStatement("SELECT id,name,hotel,attraction,distance_km FROM destinations WHERE id=?")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){return r.next()?new Destination(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5)):null;}}}
 static void save(int id,String n,String h,String a,int km)throws SQLException{String sql=id==0?"INSERT INTO destinations(name,hotel,attraction,distance_km) VALUES(?,?,?,?)":"UPDATE destinations SET name=?,hotel=?,attraction=?,distance_km=? WHERE id=?";try(Connection c=c();PreparedStatement s=c.prepareStatement(sql)){s.setString(1,n);s.setString(2,h);s.setString(3,a);s.setInt(4,km);if(id!=0)s.setInt(5,id);s.executeUpdate();}}
 static void delete(int id)throws SQLException{try(Connection c=c();PreparedStatement s=c().prepareStatement("DELETE FROM destinations WHERE id=?")){s.setInt(1,id);s.executeUpdate();}}
 static List<Object[]> users()throws SQLException{List<Object[]> a=new ArrayList<>();try(Connection c=c();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,username,role,created_at FROM app_users ORDER BY id")){while(r.next())a.add(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getTimestamp(4)});}return a;}
}
